  const hue=(a:number,b:number)=>a===0&&b===0?0:(Math.atan2(b,a)/rad+360)%360,h1=hue(ap1,b1),h2=hue(ap2,b2);
  let dh=h2-h1;if(c1*c2===0)dh=0;else if(dh>180)dh-=360;else if(dh< -180)dh+=360;
  const dl=l2-l1,dc=c2-c1,dH=2*Math.sqrt(c1*c2)*sin(dh/2),lm=(l1+l2)/2,cm=(c1+c2)/2;
  const hm=c1*c2===0?h1+h2:Math.abs(h1-h2)<=180?(h1+h2)/2:(h1+h2+(h1+h2<360?360:-360))/2;
  const t=1-.17*cos(hm-30)+.24*cos(2*hm)+.32*cos(3*hm+6)-.20*cos(4*hm-63);
  const sl=1+.015*(lm-50)**2/Math.sqrt(20+(lm-50)**2),sc=1+.045*cm,sh=1+.015*cm*t;
  const rt=-2*Math.sqrt(cm**7/(cm**7+25**7))*sin(60*Math.exp(-(((hm-275)/25)**2)));
  return Math.sqrt((dl/sl)**2+(dc/sc)**2+(dH/sh)**2+rt*(dc/sc)*(dH/sh));
