const labs=brotherThreads.map(t=>rgbToLab(t.color));
export function nearestBrother(color:string):BrotherThread {
  const lab=rgbToLab(color);let best=0,distance=Infinity;
  labs.forEach((l,i)=>{const d=deltaE2000(lab,l);if(d<distance){distance=d;best=i;}});return brotherThreads[best];
}
export function recolorObject(o:StitchObject,color:string,thread?:Thread):StitchObject {
  const next={...o,color};delete next.thread;if(thread)next.thread=thread;return next;
}
// Selection and whole-design actions return one project for the editor's single commit/undo step.
export function applyThread(p:Project,ids:readonly string[],color:string,thread?:Thread):Project {
  return {...p,objects:p.objects.map(o=>ids.includes(o.id)?recolorObject(o,color,thread):o)};
}
export function matchBrother(p:Project,ids?:readonly string[]):Project {
  return {...p,objects:p.objects.map(o=>{if(ids&&!ids.includes(o.id))return o;const t=nearestBrother(o.color),next=recolorObject(o,t.color,threadReference(t));if(o.text?.border){const b=nearestBrother(o.text.border.color);next.text={...o.text,border:{...o.text.border,color:b.color,thread:threadReference(b)}};}return next;})};
}
